  const minusMin=(t,m)=>{const x=String(t||'').match(/^(\d\d?):(\d\d)/);if(!x)return '';const v=((+x[1])*60+(+x[2])-m+1440)%1440;return String(Math.floor(v/60)).padStart(2,'0')+':'+String(v%60).padStart(2,'0')};
  const isMetroStop=s=>s.pickup_type==='Metro'||/free metro/i.test([s.name,s.address,s.landmark].join(' '));
  const metroText=s=>s.metro_description||`Avail Free Metro Pickup by showing your PNR. Drop @ ${s.exchange_point||'the interchange Metro station'}${s.exchange_time?`, before ${fmtTime(minusMin(s.exchange_time,10))}`:''} for Bus Pickup.`;
  function calPop(anchor,value,onPick,allowClear){if(G.calendarPop)return G.calendarPop(anchor,value,onPick,{clear:allowClear});document.querySelectorAll('.rv-calpop').forEach(n=>n.remove());const pop=document.createElement('div');pop.className='rv-calpop';pop.setAttribute('role','dialog');const r=anchor.getBoundingClientRect();pop.style.left=Math.max(8,Math.min(r.left,innerWidth-340))+'px';pop.style.top=(r.bottom+400>innerHeight?Math.max(8,r.top-396):r.bottom+6)+'px';
    const iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;const td=iso(new Date());let cur=value?new Date(value+'T00:00:00'):new Date();if(isNaN(cur))cur=new Date();cur.setDate(1);
    const draw=()=>{const y=cur.getFullYear(),m=cur.getMonth(),start=(new Date(y,m,1).getDay()+6)%7,days=new Date(y,m+1,0).getDate();let cells='';for(let i=0;i<start;i++)cells+='<span></span>';for(let d=1;d<=days;d++){const v=iso(new Date(y,m,d));cells+=`<button type="button" class="${v===value?'selected':''}${v===td?' today':''}" data-day="${v}">${d}</button>`}
      pop.innerHTML=`<div class="rv-cal-head"><button type="button" data-nav="-1" aria-label="Previous month">‹</button><b>${cur.toLocaleString('en-IN',{month:'long',year:'numeric'})}</b><button type="button" data-nav="1" aria-label="Next month">›</button></div><div class="rv-cal-week">${['Mo','Tu','We','Th','Fr','Sa','Su'].map(x=>`<span>${x}</span>`).join('')}</div><div class="rv-cal-grid">${cells}</div><div class="rv-cal-quick"><button type="button" data-quick="0">Today</button><button type="button" data-quick="1">Tomorrow</button><button type="button" data-quick="7">+7 days</button>${allowClear?'<button type="button" data-clear>Clear</button>':''}</div>`};
    draw();pop.addEventListener('click',e=>{e.stopPropagation();const b=e.target.closest('button');if(!b)return;if(b.dataset.nav){cur.setMonth(cur.getMonth()+Number(b.dataset.nav));draw();return}let v=null;if(b.dataset.day)v=b.dataset.day;else if(b.dataset.quick!=null){const d=new Date();d.setDate(d.getDate()+Number(b.dataset.quick));v=iso(d)}else if(b.hasAttribute('data-clear'))v='';if(v!==null){onPick(v);close()}});
    const off=e=>{if(!pop.contains(e.target)&&e.target!==anchor&&!anchor.contains(e.target))close()};const close=()=>{pop.remove();document.removeEventListener('click',off,true)};document.body.append(pop);setTimeout(()=>document.addEventListener('click',off,true),0);}
  const sourceDate=x=>x?String(x).slice(0,10):'';
  const stamp=()=>new Date().toISOString().slice(0,10);
