  const elField=(label,id,value='',type='text',extra='')=>`<label class="rv-field"><span>${E(label)}</span><input type="${type}" data-rv-field="${E(id)}" value="${E(value??'')}" ${extra}></label>`;
  const elSelect=(label,id,items,val,extra='')=>`<label class="rv-field"><span>${E(label)}</span><select data-rv-field="${E(id)}" ${extra}>${items.map(x=>{let v=Array.isArray(x)?x[0]:x,t=Array.isArray(x)?x[1]:x;return `<option value="${E(v)}" ${String(val??'')===String(v)?'selected':''}>${E(t)}</option>`}).join('')}</select></label>`;
  const basic=(text,action,cls='')=>`<button type="button" class="rv-btn ${cls}" data-rv="${E(action)}">${text}</button>`;
