      <div class="rv-route-links">${[['pickups','Pickups','↑'],['drops','Drops','↓'],['fares','Fares','₹']].map(([t,txt,g])=>`<button type="button" data-rv="open:${t}"><i>${g}</i>${txt}</button>`).join('')}</div>
