        if(action.startsWith('filter:')){status=action.slice(7);location.hash='#/gds/routes?status='+status;draw();return}
        if(action.startsWith('open:')){location.hash=`#/gds/routes/${id}?rvtab=${action.slice(5)}&rvmode=view`;return}
        if(action==='view'||action==='edit'){location.hash=`#/gds/routes/${id}?rvtab=general&rvmode=${action}`;return}
        if(action==='map'){modal('Route map — '+route.service_number,`<div class="rv-map-route"><b>${E(origin(route,cities))} → ${E(dest(route,cities))}</b><div>${E(via(route,cities).map(v=>v.name).join(' → '))}</div><p>Map stops are available on the Pickups and Drops tabs. A road-route polyline cannot be inferred from the screenshot.</p>${basic('Open route details','open-route-map','primary')}</div>`,'Close',(o,close)=>{o.querySelector('[data-rv="open-route-map"]').onclick=()=>{close();location.hash=`#/gds/routes/${id}?rvtab=cities&rvmode=view`}});return}
